        [TestMethod]
        public void Parse_FontSize_small()
        {
            StyleSheet styles = new StyleSheet();
            styles.LoadTagStyle(HtmlTags.UNORDEREDLIST, "indent", "20");
            styles.LoadTagStyle(HtmlTags.LISTITEM, "leading", "20");
            styles.LoadTagStyle(HtmlTags.ORDEREDLIST, "indent", "20");
            styles.LoadTagStyle(HtmlTags.PARAGRAPH, HtmlTags.TOPMARGIN, "40");

            string strTexto = @"<p style=""font-size:xx-small;"">Absolute size - xx-small</p>";
            var objects = HTMLWorker.ParseToList(new StringReader(strTexto), styles);
            foreach (var element in objects)
            {
                var objParagraph = new Paragraph() { KeepTogether = false, Alignment = Element.ALIGN_JUSTIFIED };
                objParagraph.Add((IElement)element);
                var objPdfPCell = new PdfPCell { HorizontalAlignment = Element.ALIGN_JUSTIFIED, Border = 0, Padding = 0, PaddingTop = 8 };
                objPdfPCell.AddElement(objParagraph);
                
            }
            Assert.AreEqual(1, objects.Count);
        }

        [TestMethod]
        public void Parse_Without_Merge_Words()
        {
            StyleSheet styles = new StyleSheet();
            styles.LoadTagStyle(HtmlTags.UNORDEREDLIST, "indent", "20");
            styles.LoadTagStyle(HtmlTags.LISTITEM, "leading", "20");
            styles.LoadTagStyle(HtmlTags.ORDEREDLIST, "indent", "20");
            styles.LoadTagStyle(HtmlTags.PARAGRAPH, HtmlTags.TOPMARGIN, "40");

            string strTexto1 = "<p style=\"text-indent: 20px; text-align: justify; \"><span style=\"font-family: 'times new roman', times; font-size: 12pt; \">A metodologia utilizada para elabora&ccedil;&atilde;o desta An&aacute;lise Global consiste na realiza&ccedil;&atilde;o de visita t&eacute;cnica &agrave; empresa para analisar o ambiente de trabalho dos trabalhadores, no intuito de identificar poss&iacute;veis altera&ccedil;&otilde;es e/ou exposi&ccedil;&atilde;o a riscos ambientais.</span></p>";
            strTexto1 += "<p style=\"text-align: justify; text-indent: 20px; \"><span style=\"font-family: 'times new roman', times; font-size: 12pt; \">Neste novo plano de a&ccedil;&atilde;o foram inseridas a&ccedil;&otilde;es que est&atilde;o em andamento, a&ccedil;&otilde;es que s&atilde;o de car&aacute;ter permanente ou seja, aquelas que sempre dever&atilde;o fazer parte do plano de a&ccedil;&atilde;o desta empresa e outras que s&atilde;o necess&aacute;rias &agrave; crit&eacute;rio da equipe t&eacute;cnica da GV Cl&iacute;nicas. Todas estas a&ccedil;&otilde;es est&atilde;o embasadas nos princ&iacute;pios das Normas Regulamentadoras e t&ecirc;m como finalidade a seguran&ccedil;a do trabalho e prote&ccedil;&atilde;o da sa&uacute;de do grupo empregat&iacute;cio.</span></p>";
            var objects = HTMLWorker.ParseToList(new StringReader(strTexto1), styles).ToArray();

            var paragraphs = objects.Where(x => x.GetType() == typeof(Paragraph)).Cast<Paragraph>().ToList();

            Assert.IsFalse(paragraphs.Any(x => x.Content.Contains("àcritério") || x.Content.Contains("àempresa")));
            Assert.IsTrue(paragraphs.Any(x => x.Content.Contains("à critério")));
            Assert.IsTrue(paragraphs.Any(x => x.Content.Contains("à empresa")));
            Assert.IsTrue(paragraphs.Any(x => x.Content.Contains("Clínicas")));
        }

         [TestMethod]
        public void Parse_Borda_ValorInvalido()
        {
            StyleSheet styles = new StyleSheet();
            styles.LoadTagStyle(HtmlTags.UNORDEREDLIST, "indent", "20");
            styles.LoadTagStyle(HtmlTags.LISTITEM, "leading", "20");
            styles.LoadTagStyle(HtmlTags.ORDEREDLIST, "indent", "20");
            styles.LoadTagStyle(HtmlTags.PARAGRAPH, HtmlTags.TOPMARGIN, "40");

            string strTexto1 = "<p><span style=\"font-size: 12pt;\">No PCMSO dos colaboradores potencialmente expostos a agentes biol&oacute;gicos infecciosos preven&iacute;veis por vacina e com status de imuniza&ccedil;&atilde;o avali&aacute;vel atrav&eacute;s de exames e testes, tais avalia&ccedil;&otilde;es devem constar no rol de exames complementares, de acordo com o momento e periodicidade preconizados pelo Minist&eacute;rio da Sa&uacute;de.</span></p><p><span style=\"font-size: 12pt;\">Dessa forma, por ocasi&atilde;o dos exames que comp&otilde;em o PCMSO, devem ser adotados os procedimentos listados no quadro abaixo.</span></p><table border=\"1\" width=\"699\"><tbody><tr><td style=\"text-align: center;\" colspan=\"4\" width=\"699\"><p>PROCEDIMENTOS M&Iacute;NIMOS OBRIGAT&Oacute;RIOS RELACIONADOS &Agrave; IMUNIZA&Ccedil;&Atilde;O NOS EXAMES M&Eacute;DICOS: ADMISSIONAL, PERI&Oacute;DICO E DE MUDAN&Ccedil;A DE FUN&Ccedil;&Atilde;O.</p></td></tr><tr><td style=\"text-align: center;\" width=\"132\"><p>PROCEDIMENTO</p></td><td style=\"text-align: center;\" width=\"198\"><p>COMPROVA&Ccedil;&Atilde;O DE VACINA&Ccedil;&Atilde;O E/OU</p><p>REFOR&Ccedil;O</p></td><td style=\"text-align: center;\" width=\"189\"><p>COMPROVA&Ccedil;&Atilde;O &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; DA</p><p>SITUA&Ccedil;&Atilde;O</p><p>SOROL&Oacute;GICA P&Oacute;S VACINA&Ccedil;&Atilde;O (NO CASO DAS VACINAS HEPATITE</p><p>B E RAIVA)</p></td><td style=\"text-align: center;\" width=\"180\"><p>IDENTIFICA&Ccedil;&Atilde;O DE NOVO AGENTE DE</p><p>RISCO BIOL&Oacute;GICO</p><p>NO PROCESSO</p><p>E/OU NO</p><p>AMBIENTE DE</p><p>TRABALHO</p></td></tr><tr><td style=\"text-align: center;\" width=\"132\"><p>Colaborador</p></td><td style=\"text-align: center;\" width=\"198\"><p>Apresentar cart&atilde;o de vacina atualizado.</p></td><td style=\"text-align: center;\" width=\"189\"><p>Deve apresentar exame comprovando a situa&ccedil;&atilde;o</p><p>sorol&oacute;gica p&oacute;s-vacina&ccedil;&atilde;o.</p></td><td style=\"text-align: center;\" width=\"180\"><p>Deve comparecer para o exame antes de assumir a nova fun&ccedil;&atilde;o/atividade.</p></td></tr><tr><td style=\"text-align: center;\" rowspan=\"3\" width=\"132\"><p>M&eacute;dico do Trabalho</p></td><td style=\"text-align: center;\" width=\"198\"><p>Verificar se todas as vacinas indicadas constam no Cart&atilde;o de Vacina&ccedil;&atilde;o como realizadas ou completadas e/ou refor&ccedil;adas, quando for o caso.</p></td><td style=\"text-align: center;\" width=\"189\"><p>Na falta da comprova&ccedil;&atilde;o de situa&ccedil;&atilde;o sorol&oacute;gica deve prescrever a vacina&ccedil;&atilde;o ou solicitar avalia&ccedil;&atilde;o da situa&ccedil;&atilde;o sorol&oacute;gica (quando poss&iacute;vel) e a seguir revacinar se for o caso.</p></td><td style=\"text-align: center;\" width=\"180\"><p>Deve confirmar a introdu&ccedil;&atilde;o do &ldquo;novo agente&rdquo; e, em caso positivo, se este &eacute; preven&iacute;vel por vacina.</p></td></tr><tr><td style=\"text-align: center;\" width=\"198\"><p>Caso falte alguma, deve encaminhar para</p><p>imuniza&ccedil;&atilde;o ou refor&ccedil;o.</p></td><td style=\"text-align: center;\" width=\"189\"><p>No caso de vacinado n&atilde;o protegido deve prescrever a vacina&ccedil;&atilde;o<a href=\"#_ftn1\" name=\"_ftnref1\">[1]</a>.</p></td><td style=\"text-align: center;\" width=\"180\"><p>Deve verificar se todas as vacinas indicadas no PCMSO para o exerc&iacute;cio seguro/ protegido naquela atividade laboral constam na CV como realizadas ou completadas e/ou refor&ccedil;adas, quando for</p><p>o caso.</p></td></tr><tr><td style=\"text-align: center;\" width=\"198\"><p>&nbsp;</p></td><td style=\"text-align: center;\" width=\"189\"><p>&nbsp;</p></td><td style=\"text-align: center;\" width=\"180\"><p>Caso falte alguma, deve encaminhar para</p><p>imuniza&ccedil;&atilde;o ou refor&ccedil;o.</p></td></tr><tr><td style=\"text-align: center;\" width=\"132\"><p>Exame Admissional</p></td><td style=\"text-align: center;\" colspan=\"2\" width=\"387\"><p>S&oacute; encerrar o exame e emitir o ASO ap&oacute;s a comprova&ccedil;&atilde;o da vacina&ccedil;&atilde;o completa, iniciada ou da situa&ccedil;&atilde;o sorol&oacute;gica.</p></td><td style=\"text-align: center;\" width=\"180\"><p>&nbsp;</p></td></tr><tr><td style=\"text-align: center;\" width=\"132\"><p>Exame Peri&oacute;dico</p></td><td style=\"text-align: center;\" colspan=\"3\" width=\"567\"><p>Deve verificar o cumprimento do calend&aacute;rio de vacina&ccedil;&atilde;o e situa&ccedil;&atilde;o sorol&oacute;gica p&oacute;s vacina&ccedil;&atilde;o (quando for o caso e apenas no primeiro peri&oacute;dico ap&oacute;s completar a vacina&ccedil;&atilde;o) e sua adequa&ccedil;&atilde;o &agrave;s fun&ccedil;&otilde;es/atividades do trabalhador.</p></td></tr><tr><td style=\"text-align: center;\" width=\"132\"><p>Exame Mudan&ccedil;a de Fun&ccedil;&atilde;o</p></td><td style=\"text-align: center;\" colspan=\"2\" width=\"387\"><p>&nbsp;</p></td><td style=\"text-align: center;\" width=\"180\"><p>S&oacute; encerrar o exame ap&oacute;s a comprova&ccedil;&atilde;o da vacina&ccedil;&atilde;o completa, iniciada ou da situa&ccedil;&atilde;o sorol&oacute;gica.</p></td></tr></tbody></table><p>&nbsp;</p><p>&nbsp;</p><h1><a name=\"_Toc533073383\"></a><strong>1.&nbsp;&nbsp; </strong><strong>ESQUEMA DE VACINA&Ccedil;&Atilde;O</strong></h1><p>Os esquemas de vacina&ccedil;&atilde;o seguiram as recomenda&ccedil;&otilde;es oficiais do Minist&eacute;rio da Sa&uacute;de.</p><p><strong>&nbsp;</strong></p><h3><a name=\"_Toc533073384\"></a>1.1. dT (difteria e t&eacute;tano)</h3><table border=\"'\" width=\"671\"><tbody><tr><td style=\"text-align: center;\" width=\"77\"><p><strong>Esquema </strong></p></td><td style=\"text-align: center;\" width=\"170\"><p><strong>Condi&ccedil;&atilde;o </strong></p></td><td style=\"text-align: center;\" width=\"424\"><p><strong>Recomenda&ccedil;&atilde;o</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p><strong>A</strong></p></td><td style=\"text-align: center;\" width=\"170\"><p>Nunca vacinado &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ou</p><p>ignorado</p></td><td style=\"text-align: center;\" width=\"424\"><p><u>Esquema b&aacute;sico</u>: 3 doses com intervalo de 2 meses entre as doses.</p><p><u>Refor&ccedil;o</u>: 1 dose a cada 10 anos.</p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p><strong>B</strong></p></td><td style=\"text-align: center;\" width=\"170\"><p>Incompleta com 1 dose</p></td><td style=\"text-align: center;\" width=\"424\"><p><u>Completar esquema b&aacute;sico</u>: 2 doses com intervalo de 2 meses.</p><p><u>Refor&ccedil;o</u>: 1 dose a cada 10 anos.</p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p><strong>C</strong></p></td><td style=\"text-align: center;\" width=\"170\"><p>Incompleta com 2 doses</p></td><td style=\"text-align: center;\" width=\"424\"><p><u>Completar esquema b&aacute;sico</u>: 1 dose ap&oacute;s 2 meses da segunda dose.</p><p><u>Refor&ccedil;o</u>: 1 dose a cada 10 anos.</p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p><strong>D</strong></p></td><td style=\"text-align: center;\" width=\"170\"><p>Completa</p></td><td style=\"text-align: center;\" width=\"424\"><p><u>Refor&ccedil;o</u>: 1 dose a cada 10 anos</p></td></tr></tbody></table><p>&nbsp;<strong>Nota: </strong></p><ul><li>Intervalos al&eacute;m dos estabelecidos n&atilde;o invalidam as doses anteriores e, portanto, n&atilde;o exige que se inicie um novo esquema.</li><li>As doses aplicadas ser&atilde;o consideradas v&aacute;lidas somente ap&oacute;s apresenta&ccedil;&atilde;o do Cart&atilde;o de Vacina devidamente registradas.</li><li><strong>Profilaxia contra o t&eacute;tano ap&oacute;s ferimento: Realizar limpeza e desbridamento da ferida. </strong></li></ul><p>&nbsp;</p><p>&nbsp;</p><h3><a name=\"_Toc533073385\"></a>Imunoprofilaxia de acordo com a imuniza&ccedil;&atilde;o pr&eacute;via</h3><table border=\"1\" width=\"671\"><tbody><tr><td style=\"text-align: center;\" rowspan=\"2\" width=\"293\"><p><strong>Varia&ccedil;&atilde;o antitet&acirc;nica </strong></p></td><td style=\"text-align: center;\" width=\"170\"><p><strong>Ferimento superficial</strong></p></td><td style=\"text-align: center;\" width=\"208\"><p><strong>Outros ferimentos</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"170\"><p><strong>Vacina</strong></p></td><td style=\"text-align: center;\" width=\"208\"><p><strong>Vacina</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"293\"><p><strong>Nunca vacinado ou ignorado ou incompleto</strong></p></td><td style=\"text-align: center;\" width=\"170\"><p>Sim</p></td><td style=\"text-align: center;\" width=\"208\"><p>Sim</p></td></tr><tr><td style=\"text-align: center;\" width=\"293\"><p><strong>Completo</strong></p></td><td style=\"text-align: center;\" width=\"170\"><p>N&atilde;o(1)</p></td><td style=\"text-align: center;\" width=\"208\"><p>N&atilde;o(2)</p></td></tr></tbody></table><p><strong>Nota: </strong></p><ul><li>Sim, se a &uacute;ltima vacina foi aplicada a mais de 10 anos.</li><li>Sim, se a &uacute;ltima vacina foi aplicada a mais de 5 anos.</li></ul><p><strong>&nbsp;</strong></p><p><strong>&nbsp;</strong></p><h3><a name=\"_Toc533073386\"></a>1.2. Febre Amarela</h3><table border=\"1\" width=\"671\"><tbody><tr><td style=\"text-align: center;\" width=\"66\"><p><strong>Esquema </strong></p></td><td style=\"text-align: center;\" width=\"228\"><p><strong>Condi&ccedil;&atilde;o </strong></p></td><td style=\"text-align: center;\" width=\"376\"><p><strong>Recomenda&ccedil;&atilde;o</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"66\"><p><strong>A</strong></p></td><td style=\"text-align: center;\" width=\"228\"><p>Nunca &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; vacinado &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ou</p><p>ignorado</p></td><td style=\"text-align: center;\" width=\"376\"><p><u>Esquema b&aacute;sico</u>: Dose &uacute;nica .</p><p><u>Refor&ccedil;o</u>: Se persistir o risco, realizar uma segunda dose 10 anos ap&oacute;s a inicial.</p></td></tr></tbody></table><p>&nbsp;</p><ul><li><strong>Hepatite B </strong></li></ul><table border=\"1\" width=\"671\"><tbody><tr><td style=\"text-align: center;\" width=\"77\"><p><strong>Esquema</strong></p></td><td style=\"text-align: center;\" width=\"131\"><p><strong>Condi&ccedil;&atilde;o</strong></p></td><td style=\"text-align: center;\" width=\"463\"><p><strong>Recomenda&ccedil;&atilde;o</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p>A</p></td><td style=\"text-align: center;\" width=\"131\"><p>Nunca vacinou ou</p><p>ignorado</p></td><td style=\"text-align: center;\" width=\"463\"><p><u>Esquema b&aacute;sico</u>: 3 doses com intervalo de 30 dias da primeira para a segunda e de 180 dias da terceira para a primeira.</p><p>&nbsp;(esquema 0 - 1 - 6 meses)</p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p>B</p></td><td style=\"text-align: center;\" width=\"131\"><p>Incompleto</p></td><td style=\"text-align: center;\" width=\"463\"><p><u>Completar esquema b&aacute;sico</u>: 1 ou 2 doses de acordo as doses recebidas respeitando intervalo m&iacute;nimo de 30 dias.</p></td></tr><tr><td style=\"text-align: center;\" width=\"77\"><p>C</p></td><td style=\"text-align: center;\" width=\"131\"><p>Exame de Anti-HBS</p><p>Negativo</p></td><td style=\"text-align: center;\" width=\"463\"><p><u>Iniciar novo esquema</u>: esquema b&aacute;sico.</p></td></tr></tbody></table><p><strong>Nota: </strong></p><ul><li>Caso ap&oacute;s o segundo esquema da vacina o exame de Anti-HBS continue com resultado Negativo, deve-se suspender novo esquema e acompanhar o empregado mediante exame de HBsAg.</li><li>Intervalos al&eacute;m dos estabelecidos n&atilde;o invalidam as doses anteriores e, portanto, n&atilde;o exige que se inicie um novo esquema.</li><li>Refor&ccedil;o n&atilde;o &eacute; necess&aacute;rio para indiv&iacute;duos imunocompetentes.</li></ul><p>&nbsp;</p><h3><a name=\"_Toc533073387\"></a>1.4. Influenza</h3><table border=\"1\" width=\"671\"><tbody><tr><td style=\"text-align: center;\" width=\"76\"><p><strong>Esquema </strong></p></td><td style=\"text-align: center;\" width=\"246\"><p><strong>Condi&ccedil;&atilde;o </strong></p></td><td style=\"text-align: center;\" width=\"350\"><p><strong>Recomenda&ccedil;&atilde;o</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"76\"><p><strong>A</strong></p></td><td style=\"text-align: center;\" width=\"246\"><p>Nunca &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; vacinado &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ou</p><p>ignorado</p></td><td style=\"text-align: center;\" width=\"350\"><p><u>Esquema b&aacute;sico</u>: Dose &uacute;nica anual;</p></td></tr></tbody></table><p>&nbsp;</p><h3><a name=\"_Toc533073388\"></a>1.5. Triviral (sarampo, caxumba e rub&eacute;ola)</h3><table border=\"1\" width=\"671\"><tbody><tr><td style=\"text-align: center;\" width=\"76\"><p><strong>Esquema </strong></p></td><td style=\"text-align: center;\" width=\"246\"><p><strong>Condi&ccedil;&atilde;o </strong></p></td><td style=\"text-align: center;\" width=\"350\"><p><strong>Recomenda&ccedil;&atilde;o</strong></p></td></tr><tr><td style=\"text-align: center;\" width=\"76\"><p><strong>A</strong></p></td><td style=\"text-align: center;\" width=\"246\"><p>Nunca &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; vacinado &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ou</p><p>ignorado</p></td><td style=\"text-align: center;\" width=\"350\"><p><u>Esquema b&aacute;sico</u>: Duas doses at&eacute; 29 anos, Uma dose &gt;30 anos</p></td></tr><tr><td style=\"text-align: center;\" width=\"76\"><p><strong>B</strong></p></td><td style=\"text-align: center;\" width=\"246\"><p>Incompleta at&eacute; 29 anos</p></td><td style=\"text-align: center;\" width=\"350\"><p><u>Completar esquema b&aacute;sico</u>: 1 doses com intervalo de 2 meses.</p></td></tr></tbody></table><p><strong>Nota 1:</strong> Deve-se respeitar o intervalo m&iacute;nimo de 30 dias entre a administra&ccedil;&atilde;o das vacinas Triviral e Febre Amarela.</p><p><strong>Nota 2:</strong> Idade m&aacute;xima de 49 anos.</p><p>&nbsp;</p><h1><strong>2.&nbsp;&nbsp; </strong><strong>Demais Informa&ccedil;&otilde;es </strong></h1><p>As informa&ccedil;&otilde;es adicionais referente ao procedimentos e a&ccedil;&otilde;es relacionadas a Imuniza&ccedil;&atilde;o constam no Programa de Imuniza&ccedil;&atilde;o Ativa &ndash; PIA.</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p><a href=\"#_ftnref1\" name=\"_ftn1\">[1]</a> A queda de n&iacute;vel de anticorpos para hepatite B ao longo do tempo, ap&oacute;s a terceira dose da vacina, ocorre e n&atilde;o e raro o resultado anti-Hbs negativo quando o exame &eacute; realizado mais de 60 dias ap&oacute;s completado o esquema vacinal. Nesta situa&ccedil;&atilde;o, deve-se repetir as tr&ecirc;s doses da vacina (apenas uma vez e n&atilde;o mais do que isso) ou aplicar uma dose (para desafiar o sistema imunol&oacute;gico) e repetir sorologia (anti-Hbs) 30 a 60 dias ap&oacute;s.</p>";
            var objects = HTMLWorker.ParseToList(new StringReader(strTexto1), styles).ToArray();

            var paragraphs = objects.Where(x => x.GetType() == typeof(Paragraph)).Cast<Paragraph>();

        }
    }
